package com.logiplatform.model;

import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;

@Entity @Table(name="rail_consignments") public class RailConsignment { @Id @GeneratedValue UUID id; @Column(name="tenant_id",nullable=false,updatable=false) UUID tenantId; @Column(name="shipment_id",nullable=false) UUID shipmentId; String railConsignmentNumber,trainNumber,wagonNumbers,originTerminal,destinationTerminal; Instant plannedDeparture,plannedArrival; String status="PLANNED"; Instant createdAt=Instant.now(),updatedAt=Instant.now(); protected RailConsignment(){} public RailConsignment(UUID t,UUID s,String no,String train,String wagons,String origin,String dest){tenantId=t;shipmentId=s;railConsignmentNumber=no;trainNumber=train;wagonNumbers=wagons;originTerminal=origin;destinationTerminal=dest;} public UUID getId(){return id;} public UUID getShipmentId(){return shipmentId;} public String getRailConsignmentNumber(){return railConsignmentNumber;} public String getTrainNumber(){return trainNumber;} public String getWagonNumbers(){return wagonNumbers;} public String getOriginTerminal(){return originTerminal;} public String getDestinationTerminal(){return destinationTerminal;} public String getStatus(){return status;} }
